import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/tui/shortcuts.md","filePath":"openshield-xdp/tui/shortcuts.md","lastUpdated":1782568991000}'),r={name:"openshield-xdp/tui/shortcuts.md"};function c(n,t,i,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Complete keybinding reference for the OpenShield-XDP TUI.</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Toggle help overlay</td><td><code>?</code></td></tr><tr><td>Close help overlay</td><td><code>?</code>, <code>Esc</code>, <code>q</code></td></tr><tr><td>Quit</td><td><code>q</code>, <code>Ctrl+C</code></td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Dashboard</td><td><code>1</code></td></tr><tr><td>Traffic</td><td><code>2</code></td></tr><tr><td>Attacks</td><td><code>3</code></td></tr><tr><td>Bans</td><td><code>4</code></td></tr><tr><td>Logs</td><td><code>5</code></td></tr><tr><td>Status</td><td><code>6</code></td></tr><tr><td>Config</td><td><code>7</code></td></tr><tr><td>Next screen</td><td><code>Tab</code></td></tr><tr><td>Previous screen</td><td><code>Shift+Tab</code></td></tr><tr><td>Click nav tab</td><td>Mouse left-click on tab label</td></tr></tbody></table><h2 id="logs-screen-5" tabindex="-1">Logs screen (<code>5</code>) <a class="header-anchor" href="#logs-screen-5" aria-label="Permalink to &quot;Logs screen (`5`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Scroll down (1 line)</td><td><code>j</code>, <code>↓</code></td></tr><tr><td>Scroll up (1 line)</td><td><code>k</code>, <code>↑</code></td></tr><tr><td>Page down</td><td><code>PgDn</code></td></tr><tr><td>Page up</td><td><code>PgUp</code></td></tr><tr><td>Jump to bottom</td><td><code>G</code></td></tr><tr><td>Jump to top</td><td><code>g</code></td></tr><tr><td>Search/filter</td><td><code>/</code> (type query, <code>Esc</code> to clear, <code>Enter</code> to confirm)</td></tr><tr><td>Clear search</td><td><code>Esc</code></td></tr><tr><td>Toggle line wrapping</td><td><code>w</code></td></tr><tr><td>Scroll (mouse)</td><td>Scroll wheel up/down</td></tr></tbody></table><h2 id="bans-screen-4" tabindex="-1">Bans screen (<code>4</code>) <a class="header-anchor" href="#bans-screen-4" aria-label="Permalink to &quot;Bans screen (`4`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Next page</td><td><code>n</code></td></tr><tr><td>Previous page</td><td><code>p</code></td></tr><tr><td>Search by IP/reason</td><td><code>/</code> (type query, <code>Esc</code> to clear)</td></tr><tr><td>Clear search</td><td><code>Esc</code></td></tr><tr><td>Scroll pages (mouse)</td><td>Scroll wheel up/down</td></tr></tbody></table><h2 id="attacks-screen-3" tabindex="-1">Attacks screen (<code>3</code>) <a class="header-anchor" href="#attacks-screen-3" aria-label="Permalink to &quot;Attacks screen (`3`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Next page of offenders</td><td><code>n</code></td></tr><tr><td>Previous page of offenders</td><td><code>p</code></td></tr></tbody></table><h2 id="config-screen-7" tabindex="-1">Config screen (<code>7</code>) <a class="header-anchor" href="#config-screen-7" aria-label="Permalink to &quot;Config screen (`7`)&quot;">​</a></h2><h3 id="browse-mode" tabindex="-1">Browse mode <a class="header-anchor" href="#browse-mode" aria-label="Permalink to &quot;Browse mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Move cursor down</td><td><code>↓</code>, <code>j</code>, <code>Tab</code></td></tr><tr><td>Move cursor up</td><td><code>↑</code>, <code>k</code>, <code>Shift+Tab</code></td></tr><tr><td>Edit selected field</td><td><code>Enter</code> (runtime-safe fields only)</td></tr><tr><td>Toggle read-only fields visibility</td><td><code>r</code></td></tr><tr><td>Preview and apply pending changes</td><td><code>a</code></td></tr><tr><td>Discard all pending changes</td><td><code>d</code></td></tr><tr><td>Revert individual field</td><td><code>x</code></td></tr></tbody></table><h3 id="edit-mode" tabindex="-1">Edit mode <a class="header-anchor" href="#edit-mode" aria-label="Permalink to &quot;Edit mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Save edited value</td><td><code>Enter</code></td></tr><tr><td>Cancel editing</td><td><code>Esc</code></td></tr><tr><td>Delete last character</td><td><code>Backspace</code></td></tr><tr><td>Type characters</td><td>Any printable ASCII</td></tr></tbody></table><h3 id="preview-mode" tabindex="-1">Preview mode <a class="header-anchor" href="#preview-mode" aria-label="Permalink to &quot;Preview mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Confirm and apply changes</td><td><code>y</code></td></tr><tr><td>Cancel</td><td><code>n</code>, <code>Esc</code></td></tr></tbody></table><h3 id="confirmation-dialog" tabindex="-1">Confirmation dialog <a class="header-anchor" href="#confirmation-dialog" aria-label="Permalink to &quot;Confirmation dialog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Confirm</td><td><code>y</code></td></tr><tr><td>Cancel</td><td><code>n</code>, <code>Esc</code></td></tr></tbody></table><h2 id="mouse" tabindex="-1">Mouse <a class="header-anchor" href="#mouse" aria-label="Permalink to &quot;Mouse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Gesture</th></tr></thead><tbody><tr><td>Switch screen</td><td>Click nav tab in navigation bar</td></tr><tr><td>Scroll logs</td><td>Scroll wheel (anywhere on logs screen)</td></tr><tr><td>Scroll bans</td><td>Scroll wheel (anywhere on bans screen)</td></tr></tbody></table><h2 id="search-mode" tabindex="-1">Search mode <a class="header-anchor" href="#search-mode" aria-label="Permalink to &quot;Search mode&quot;">​</a></h2><p>When search is active (<code>/</code> pressed on Logs or Bans screen):</p><table tabindex="0"><thead><tr><th>Action</th><th>Key(s)</th></tr></thead><tbody><tr><td>Add character</td><td>Type any printable ASCII</td></tr><tr><td>Delete last character</td><td><code>Backspace</code></td></tr><tr><td>Confirm search</td><td><code>Enter</code></td></tr><tr><td>Cancel search</td><td><code>Esc</code></td></tr></tbody></table><p>The hint bar displays the current search query while in search mode. Matching entries are filtered in real-time as you type.</p><h2 id="visual-indicators" tabindex="-1">Visual indicators <a class="header-anchor" href="#visual-indicators" aria-label="Permalink to &quot;Visual indicators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>&gt;</code> (cyan)</td><td>Currently selected config field</td></tr><tr><td><code>*</code> (yellow)</td><td>Field has a pending change</td></tr><tr><td><code>[RO]</code> (dimmed)</td><td>Read-only field</td></tr><tr><td>Red text</td><td>Error, ban event, under attack</td></tr><tr><td>Yellow text</td><td>Warning, suspect IP, pending changes</td></tr><tr><td>Green text</td><td>OK, normal, healthy</td></tr><tr><td>Dimmed text</td><td>Secondary info, read-only, inactive</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/tui/screens">TUI Screens Deep-Dive</a> · <a href="/pingless-studios-docs/openshield-xdp/tui/overview">TUI Overview</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/commands">CLI Reference</a></p>',31)])])}const p=e(r,[["render",c]]);export{u as __pageData,p as default};
